import{_ as t,a,o as s,a4 as r}from"./chunks/framework.-FZumj2l.js";const g=JSON.parse('{"title":"Settings","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/settings/index.md","filePath":"api/graphql-api/admin/settings/index.md","lastUpdated":1783079210000}'),o={name:"api/graphql-api/admin/settings/index.md"};function n(i,e,d,c,l,h){return s(),a("div",null,e[0]||(e[0]=[r('<h1 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h1><p>The Settings section is where you configure the store itself — the languages and currencies it speaks, the storefronts it runs, the people who manage it, how tax is calculated, the look of the storefront, and bulk data import. These are the foundational records most other parts of the admin depend on: a product needs a tax category, an order needs a channel and a currency, an admin needs a role.</p><h2 id="menus" tabindex="-1">Menus <a class="header-anchor" href="#menus" aria-label="Permalink to &quot;Menus&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Menu</th><th>What it&#39;s for</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/admin/settings/locales/">Locales</a></td><td>The languages (locale code, name, text direction, optional flag) the storefront can be shown in. Channels pick which locales they offer.</td></tr><tr><td><a href="/api/graphql-api/admin/settings/currencies/">Currencies</a></td><td>The currencies the store can price and display in, plus each one&#39;s formatting — symbol, decimal places, separators, symbol position.</td></tr><tr><td><a href="/api/graphql-api/admin/settings/exchange-rates/">Exchange Rates</a></td><td>The conversion rate from the base currency to each target currency, used to show prices in other currencies. Includes a one-click auto-sync from an external rate provider.</td></tr><tr><td><a href="/api/graphql-api/admin/settings/inventory-sources/">Inventory Sources</a></td><td>The stock locations products draw quantity from. Channels are served from sources, and shipments ship from a chosen source.</td></tr><tr><td><a href="/api/graphql-api/admin/settings/channels/">Channels</a></td><td>The storefronts — each with its own hostname, theme, default + allowed locales, base + allowed currencies, inventory sources, root category, and SEO / maintenance settings.</td></tr><tr><td><a href="/api/graphql-api/admin/settings/users/">Admin Users</a></td><td>The back-office accounts that sign into the admin panel, each assigned a Role that grants their permissions.</td></tr><tr><td><a href="/api/graphql-api/admin/settings/roles/">Roles</a></td><td>Named permission sets assigned to admin users — they decide what each admin can see and do.</td></tr><tr><td><a href="/api/graphql-api/admin/settings/themes/">Themes</a></td><td>Per-channel storefront content blocks — carousels, static content, footer links, service blocks — and their per-locale content. (Not installable themes.)</td></tr><tr><td><a href="/api/graphql-api/admin/settings/tax-categories/">Tax Categories</a></td><td>Named groups of tax rates that get assigned to products — the bridge between a product and the rates that apply to it.</td></tr><tr><td><a href="/api/graphql-api/admin/settings/tax-rates/">Tax Rates</a></td><td>The individual rate rules — a percentage for a country / state and a zip or zip range — that tax categories are built from.</td></tr><tr><td><a href="/api/graphql-api/admin/settings/data-transfer-imports/overview.html">Data Transfer Imports</a></td><td>Bulk-import products, customers, tax rates and more from CSV / XLSX, with a validate → start → link → index pipeline you drive step by step.</td></tr></tbody></table><h2 id="how-these-records-relate" tabindex="-1">How these records relate <a class="header-anchor" href="#how-these-records-relate" aria-label="Permalink to &quot;How these records relate&quot;">​</a></h2><ul><li>A <strong>Channel</strong> is assembled from other Settings records: it picks its <strong>Locales</strong>, its <strong>Currencies</strong> (one of them the base), its <strong>Inventory Sources</strong>, and a root <strong>Category</strong>. <strong>Exchange Rates</strong> convert the base currency into the channel&#39;s other currencies for display.</li><li>An <strong>Admin User</strong> is granted access through its <strong>Role</strong>. A role with permission type <em>custom</em> carries an explicit list of permission keys; <em>all</em> grants everything.</li><li>A product&#39;s tax is decided by the <strong>Tax Category</strong> assigned to it, which is a group of <strong>Tax Rates</strong> (each rate matching a country/state + zip).</li></ul><h2 id="conventions-across-the-settings-api" tabindex="-1">Conventions across the Settings API <a class="header-anchor" href="#conventions-across-the-settings-api" aria-label="Permalink to &quot;Conventions across the Settings API&quot;">​</a></h2><p>A few behaviours are common to every Settings menu over GraphQL:</p><ul><li><strong>Listings are cursor connections.</strong> Every list query returns <code>edges { cursor node { … } } pageInfo { hasNextPage hasPreviousPage startCursor endCursor } totalCount</code>. Page with <code>first</code> + <code>after</code>.</li><li><strong>Delete returns a snapshot of what was removed.</strong> A delete mutation returns the just-deleted record, so you can select <code>id</code>, <code>_id</code> and its fields to confirm exactly what was deleted.</li><li><strong>Mass-delete returns a plain id list.</strong> A mass-delete (or mass-update-status) returns <code>deleted</code> / <code>skipped</code> / <code>updated</code> as plain integer arrays, plus a <code>message</code> string.</li><li><strong>Some fields are JSON, queried bare.</strong> Fields like a channel&#39;s <code>homeSeo</code> (or a translation node&#39;s per-locale <code>homeSeo</code>) are returned as whole JSON values — select them by name with <strong>no</strong> sub-selection. A channel&#39;s <code>locales</code> / <code>currencies</code> / <code>inventorySources</code> / <code>translations</code>, by contrast, are object connections — sub-select <code>{ edges { node { … } } }</code>.</li></ul><p>All Settings operations require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p>',10)]))}const u=t(o,[["render",n]]);export{g as __pageData,u as default};
